<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use App\Http\Requests\{RegisterRequest,LoginRequest};use App\Http\Resources\UserResource;use App\Services\AuthenticationService;use App\Support\ApiResponse;
class AuthController extends Controller { public function __construct(private AuthenticationService $auth,private ApiResponse $response){} public function register(RegisterRequest $r){[$u,$t]=$this->auth->register($r->validated());return $this->response->success('Registration successful.',['user'=>new UserResource($u),'token'=>$t],201);} public function login(LoginRequest $r){[$u,$t]=$this->auth->login($r->validated());return $this->response->success('Login successful.',['user'=>new UserResource($u),'token'=>$t]);} public function logout(Request $r){$this->auth->logout($this->token($r));return $this->response->success('Logout successful.');} public function me(Request $r){return $this->response->success('Authenticated user retrieved successfully.',new UserResource($r->user()));} private function token(Request $r):string{return preg_replace('/^Bearer\s+/i','',$r->header('Authorization',''));} }
